head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > M > unbindRef]<br/>Multiselect 컴포넌트의 ref 속성값을 제거합니다.",
    "validation" : [
        "메소드 호출 시 컴포넌트의 ref 속성값이 제거됩니다.",
        "메소드로 ref 속성값을 제거해도 컴포넌트에 선택된 아이템은 유지됩니다.",
        "ref 속성값 제거 후에는 아이템 선택을 변경해도 기존에 바인딩되어 있던 DataCollection 에 반영되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 (gdl_multiselect 포함)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// onchange 이벤트 핸들러 — multiselect onchange 는 파라미터 없음 (engine spec)
scwin.target1_onchange = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};



// unbindRef: ref 속성값 제거
scwin.btn_unbindRef_onclick = function (e) {
    target1.unbindRef();
    wf_body_bottom.getObj("scwin").setReturnValue("unbindRef() 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("options.ref : '" + target1.options.ref + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};



// 아이템 선택 (선택 아이템 유지 검증용) - setSelectedIndex 로 아이템 선택
scwin.btn_selectItem_onclick = function (e) {
    target1.setSelectedIndex("0,2");
    wf_body_bottom.getObj("scwin").setReturnValue("setSelectedIndex('0,2') 호출");
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};



// getValue: 호출 후 결과 출력 (선택 아이템 유지 검증)
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + target1.getValue());
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : " + target1.getSelectedIndex());
};



// 바인딩 해제 검증: dlt_ref 의 현재 row 값 확인 (unbindRef 후 아이템 변경이 반영되지 않음)
scwin.btn_getDataList_onclick = function (e) {
    let rsData = dlt_ref.getAllJSON();
    for (let i = 0; i < rsData.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + i + " value : " + rsData[i].value);
    }
};
